        assign product_level_promotion_metafield_value = product | product_metafield: 'custom.product_level_promotion_rich_text'

        if product_level_promotion_metafield_value != blank
          assign raw = product_level_promotion_metafield_value
          assign parts = raw | split: '"value":"'
          assign promotion_text = ''
          assign bold_text = ''
          assign normal_text = ''
          assign index = 0

          for part in parts
            if index > 0 and part contains '"'
              assign text_piece = part | split: '"' | first
              assign text_piece = text_piece | replace: '\n', '<br>' | replace: '\r', '' | strip
              if index == 1
                assign bold_text = text_piece
              else
                assign normal_text = normal_text | append: text_piece | append: '<br>'
              endif
            endif
            assign index = index | plus: 1
          endfor

          assign promotion_html = '<div class="price price__discount-code price__metafield-data"><div class="metafield-rich_text_field"><p>'
          if bold_text != ''
            assign promotion_html = promotion_html | append: '<strong>' | append: bold_text | append: '</strong>'
          endif
          assign promotion_html = promotion_html | append: normal_text | append: '</p></div></div>'

          echo promotion_html
        endif
      -%}
                  {% capture metaData %}
                  {
                  "action": {
                  {% if product.variants.size == 1 %}
                  "addToCart": {
                  "productId": "{{ product.variants[0].id }}",
                  {% assign sellingPlanId = '' %}
                  {% if product.variants[0].preorder and product.variants[0].preorder.sellingPlan %}
                  {% assign sellingPlanId = product.variants[0].preorder.sellingPlan.id %}
                  {% else %}
                  {% assign sellingPlanId = '' %}
                  {% endif %}
                  "selling_plan": {{ sellingPlanId | json | escape }}
                  }
                  {% else %}
                  "quickView": {
                  "productId": "{{ product.id }}",
                  "fromSelectOptionBtn": true
                  }
                  {% endif %}
                  }
                  }
                  {% endcapture %}
                  {% assign variantPreorder = product.variants[0].preorder %}
                  {% assign buttonPreorder = '' %}
                  {% if variantPreorder %}
                  {% assign buttonPreorder = buttonPreorder | append : ' boost-sd__button--preorder' %}
                  {% endif %}
                  {% assign buttonTextPreorder = '' %}
                  {% if variantPreorder %}
                  {% assign buttonTextPreorder = buttonTextPreorder | append : ' boost-sd__button-text--preorder' %}
                  {% endif %}
                  {% assign preOrderLabel = 'Pre-Order' %}
                  {% assign preOrderButtonText = product.variants[0].preorder.settings.buttonText %}
                  {% if preOrderButtonText and preOrderButtonText != '' %}
                  {% assign preOrderLabel = preOrderButtonText %}
                  {% endif %}
                  {% assign selectOptionBtnLabel = '' %}
                  {% if product.available == false %}
                  {% assign selectOptionBtnLabel = "productItem.soldoutLabel" | translate: translations, 'Sold out' %}
                  {% elsif product.variants.size == 1 %}
                  {% assign selectOptionBtnLabel = "productItem.atcAvailableLabel" | translate: translations, 'Add to cart' %}
                  <!-- TODO check preorder -->
                  {% if variantPreorder %}
                  {% assign selectOptionBtnLabel = preOrderLabel %}
                  {% endif %}
                  {% else %}
                  {% assign selectOptionBtnLabel = "productItem.atcSelectOptionsLabel" | translate: translations, 'Choose options' %}
                  {% endif %}
                  <button aria-label='{{ selectOptionBtnLabel }}' class='boost-sd__button boost-sd__button--select-option boost-sd__button--border boost-sd__button--show-on-hover boost-sd__button--capsule boost-sd__button--left boost-sd__button--full-width{{ buttonPreorder }}' type='button' {% if product.available == false %} disabled {% endif %} data-metadata='{{ metaData | json_encode }}'>
                    <span class='boost-sd__button-text boost-sd__cta-button-text {{ buttonTextPreorder }}'>{{ selectOptionBtnLabel }}</span>
                  </button>
                </div>
              </div>
            </div>
          </div>
          {% endif %}
          {% endfor %}
          <!-- Render a banner only if it is immediately after the last item (ie if there is a banner with position == index + 1) -->
          {% assign productSize = products.size %}
          {% assign lastIndex = index %}
          {% for banner in sorted_banners %}
          {% assign bannerPos = banner.position | plus: 1 %}
          {% assign expectedPosition = lastIndex | plus: 1 %}
          {% if request.page == totalPage and bannerPos == expectedPosition and productSize <= requestLimit %}
          <div class='boost-sd__product-item boost-sd__product-item--{{ borderLayoutItem }} boost-sd__product-item-grid-view-layout boost-sd__product-item--last'>
            {%- capture aspectRatioSetting %}natural{% endcapture -%}
            {% assign aspectRatio = '' -%}
            {% if aspectRatioSetting == 'natural' -%}
            {% for product in products %}
            {% assign imageWidth = product.images_info[0].width -%}
            {% assign imageHeight = product.images_info[0].height -%}
            {% endfor %}
            {% assign aspectRatio = aspectRatio | append: 'aspect-ratio: ' | append: imageWidth | append: '/' | append: imageHeight -%}
            {% endif -%}
            <div class="boost-sd__product-image-wrapper boost-sd__product-image-wrapper--natural" style="{{ aspectRatio }}">
              <div class="boost-sd__product-banner">
                <a class="boost-sd__product-banner-link" href="{{ banner.link }}" target="{% if banner.openInNewTab == true %}_blank{% else %}_self{% endif %}" alt="{{ banner.name }}">
                  <img class="boost-sd__product-banner-image" src="{{ banner.imgSrc }}" alt="{{ banner.name }}" width="auto" height="auto" />
                </a>
              </div>
            </div>
          </div>
          {% break %}
          {% endif %}
          {% endfor %}
        </div>
        {% assign position = 'bottom' %}
        <!-- TEMPLATE PAGINATION -->
        {% assign requestLimit = request.limit | times: 1.0 -%}
        {% assign totalPage = total_product | times: 1 | divided_by: requestLimit | ceil -%}
        {% assign showLoadPrev = false %}
        {% if request.page != 1 and position == 'top' %}
        {% assign showLoadPrev = true %}
        {% endif %}
        {% assign showLoadMore = false %}
        {% if request.page != totalPage and position == 'bottom' %}
        {% assign showLoadMore = true %}
        {% endif %}
        {% if showLoadPrev %}
        {% endif %}
        {% if showLoadMore %}
        {% endif %}
        {% if position == 'top' and request.page != 1 %}
        <!-- TEMPLATE PAGINATION INFINITE SCROLL -->
        <div class="boost-sd__pagination-infinite-scroll-container-button" data-position="{{ position | escape }}">
          <button type="button" aria-label="previous page" class="boost-sd__pagination-button boost-sd__pagination-button--rectangle boost-sd__pagination-button--load-more">
            <span class="boost-sd__pagination-button-text">{{ "pagination.loadPreviousInfiniteText" | translate: translations, "Load Previous Page" }}</span>
          </button>
        </div>
        {% endif %}
        {% if showLoadPrev %}
        {% endif %}
        {% if showLoadMore %}
        {% endif %}
        {% if position == 'bottom' %}
        <div class="boost-sd__pagination-infinite-scroll-container-target" style="text-align: center; opacity: 0; visibility: hidden;">Loading...</div>
        {% endif %}
        {% endif %}
      </div>
    </div>
  </div>
  {% if statusNewSI == 'true'%}
</div>
{% endif %}"}
